const sales = await t5.call("local_file", { action: "read", path: "GPAO-T5/2026-07 정산/2026-07 매출정산.csv" });
const details = await t5.call("local_file", { action: "read", path: "GPAO-T5/2026-07 정산/7월 정산내역.csv" });

// 간단한 정리: 두 파일의 표 데이터를 합쳐 거래처별 합계를 낸다.
function parseCSV(text) {
  const lines = text.trim().split(/\r?\n/);
  const header = lines[0].split(",").map(h => h.trim());
  const rows = lines.slice(1).map(line => {
    const cols = line.split(",");
    const obj = {};
    header.forEach((h, i) => {
      obj[h] = (cols[i] || "").trim();
    });
    return obj;
  }).filter(r => Object.values(r).some(v => v !== ""));
  return { header, rows };
}

const salesTable = sales.table || parseCSV(sales.text);
const detailsTable = details.table || parseCSV(details.text);

// 거래처별 금액 합계 계산
function sumByClient(table) {
  const result = {};
  for (const row of table.rows) {
    const client = row["거래처"] || "(미입력)";
    const amount = parseInt(String(row["금액"]).replace(/[^0-9-]/g, "")) || 0;
    result[client] = (result[client] || 0) + amount;
  }
  return result;
}

const salesSum = sumByClient(salesTable);
const detailsSum = sumByClient(detailsTable);

// 전체 합계와 차이 계산
function total(sumObj) { return Object.values(sumObj).reduce((a,b)=>a+b,0); }

const salesTotal = total(salesSum);
const detailsTotal = total(detailsSum);
const diff = salesTotal - detailsTotal;

console.log({
  ok: true,
  summary: "2026-07 정산 파일 거래처별 합계 및 파일 간 차이 정리",
  result: {
    salesByClient: salesSum,
    detailsByClient: detailsSum,
    salesTotal,
    detailsTotal,
    diff,
  }
});
